// The prompt and command pages share the exact help generated by the CLI.
import { SIGMA_AI_PROMPT } from './prompt-data.js';

export const commands = SIGMA_AI_PROMPT.split('\n' + '='.repeat(60) + '\n').slice(1).map(help => {
  const heading = help.split('\n')[0];
  const match = /^sigma ([a-z-]+) — (.*)$/.exec(heading);
  if (!match) throw new Error('Invalid generated command help');
  const [, name, description] = match;
  const usage = /\nUSAGE: ([^\n]+)/.exec(help)?.[1] || '';
  const options = /\nOPTIONS:\n([\s\S]*?)\n\nEXAMPLE:/.exec(help)?.[1].trimEnd() || '';
  const example = /\nEXAMPLE:\n([\s\S]*?)\n\nOptions may/.exec(help)?.[1].trim() || '';
  return { name, description, usage, options, example };
});

const categoryNames = [
  ['Init', ['init', 'status', 'backup', 'restore', 'help']],
  ['Accounts', ['account-create', 'account-list', 'account-default', 'account-delete']],
  ['Agents', ['agent-connect', 'agent-list', 'agent-stop', 'agent-model', 'agent-models', 'agent-master', 'agent-permissions', 'agent-act']],
  ['Calls', ['agent-calls', 'agent-call-cancel']],
  ['Profile', ['set-profile-photo']],
  ['Messages', ['send-message', 'reply', 'send-file', 'send-photo', 'send-voice', 'chats', 'messages', 'receive', 'read-messages', 'listen', 'search-messages', 'edit-message', 'delete-message', 'forward-message', 'react', 'reactions', 'download-file', 'export-file']],
  ['Groups', ['create-group', 'join-group', 'invite-to-group', 'add-to-group', 'group-members', 'remove-from-group', 'rename-group', 'set-group-photo', 'group-link', 'leave-group']],
  ['Channels', ['create-channel', 'join-channel', 'invite-to-channel', 'channel-members', 'remove-from-channel', 'rename-channel', 'set-channel-description', 'set-channel-photo', 'channel-link', 'send-channel-message', 'leave-channel']],
  ['Hooks', ['chat-hook-add', 'chat-hook-list', 'chat-hook-remove', 'app-hook-add', 'app-hook-list', 'app-hook-remove']],
  ['Contacts', ['create-contact', 'add-contact', 'contacts', 'securejoin-id', 'join-link', 'give-qr']],
  ['Webxdc apps', ['send-webxdc', 'app-list', 'app-info', 'app-bind', 'app-run', 'app-start', 'app-stop', 'app-send', 'app-update', 'app-events', 'send-webxdc-realtime', 'listen-webxdc-realtime', 'send-webxdc-update', 'webxdc-updates', 'listen-webxdc-updates']]
];

export const commandGroups = categoryNames.map(([title, names]) => ({
  title,
  commands: names.map(name => commands.find(command => command.name === name))
}));
// Fail visibly if generated help adds a command that needs categorizing.
const grouped = commandGroups.flatMap(group => group.commands);
if (grouped.some(command => !command) || new Set(grouped.map(command => command.name)).size !== commands.length || grouped.length !== commands.length) {
  throw new Error('Every CLI command must appear in exactly one documentation group');
}
